function stableContent(host,html){
 const template=document.createElement('template');template.innerHTML=html;
 const existing=[...host.childNodes];let cursor=host.firstChild;
 for(const candidate of [...template.content.childNodes]){
  const match=existing.find(node=>node.isEqualNode(candidate));
  const node=match||candidate;if(match)existing.splice(existing.indexOf(match),1);
  if(node!==cursor)host.insertBefore(node,cursor);cursor=node.nextSibling;
 }
 for(const node of existing)node.remove();
}
